import (
	"context"
	"fmt"
	"log"

	"github.com/haau3/haau3-go"
)

func main() {
	ctx := context.Background()
	client, err := haau3.NewClient() // reads HAAU3_API_KEY
	if err != nil {
		log.Fatal(err)
	}
	entry1 := haau3.Calls.CodeSystemLookup(haau3.CodeSystemLookupParams{Code: "2345-7", System: new("http://loinc.org"), Property: []string{"SHORTNAME"}})
	entry2 := haau3.Calls.CodeSystemLookup(haau3.CodeSystemLookupParams{Code: "8867-4", System: new("http://loinc.org"), Property: []string{"SHORTNAME"}})
	entry3 := haau3.Calls.ListInsurancePlanCounties(haau3.ListInsurancePlanCountiesParams{State: "DE"})
	if err := client.Batch(ctx, []haau3.Entry{entry1, entry2, entry3}); err != nil {
		log.Fatal(err)
	}
	show(entry1.Result())
	show(entry2.Result())
	show(entry3.Result())
}

// show prints that one entry of the batch answered, or why it failed.
func show[T any](_ T, err error) {
	if err != nil {
		fmt.Println(err)
		return
	}
	fmt.Println("ok")
}

