import (
	"context"
	"encoding/json"
	"fmt"
	"log"
	"os"

	"github.com/haau3/haau3-go"
	"github.com/haau3/haau3-go/fhir"
)

func main() {
	ctx := context.Background()
	client, err := haau3.NewClient() // reads HAAU3_API_KEY
	if err != nil {
		log.Fatal(err)
	}
	data, err := os.ReadFile("request.json") // a pharmacy benefit check without patient details
	if err != nil {
		log.Fatal(err)
	}
	var body fhir.Bundle
	if err := json.Unmarshal(data, &body); err != nil {
		log.Fatal(err)
	}
	bundle, err := client.ProcessMessage(ctx, &body)
	if err != nil {
		log.Fatal(err)
	}
	fmt.Println(len(bundle.Entry))
}

