)

func main() {
	ctx := context.Background()
	client, err := haau3.NewClient() // reads HAAU3_API_KEY
	if err != nil {
		log.Fatal(err)
	}
	data, err := os.ReadFile("request.json") // a test member's pharmacy benefit check
	if err != nil {
		log.Fatal(err)
	}
	var body fhir.Bundle
	if err := json.Unmarshal(data, &body); err != nil {
		log.Fatal(err)
	}
